#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    int globalMax = 0;

    #pragma omp parallel
    {
        int localMax = 0;

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            int deg = 0;
            const size_t rowBase = static_cast<size_t>(i) * N;

            for (size_t j = 0; j < N; ++j) {
                deg += (A[rowBase + j] != 0) ? 1 : 0;
            }

            if (deg > localMax) localMax = deg;
        }

        #pragma omp critical
        {
            if (localMax > globalMax) globalMax = localMax;
        }
    }

    return globalMax;
}
